docReady(function() {
		var mCookies = new UniversalCookie();
		if (mCookies.get('flash')) {
				var cookieMsg = getMessagesFromCookies(mCookies.get('flash'));
				var dom = document.getElementById("modyo-site-alert-wrapper");
				var node = document.createElement("div");
				node.classList.add('alert');
				node.classList.add('alert-' + cookieMsg.type);
				node.appendChild(document.createTextNode(cookieMsg.messages[0]));
				dom.appendChild(node);
				setTimeout(function(){
					dom.removeChild(node);
				}, 5000)
		}
		mCookies.remove('flash', { path: '/', secure: true });
});

	

