async function generateAnimationEmpresariales() {
	try {
		
		LottieInteractivity.create({
				player: '#soluciones-empresariales',
				container: '.animate-bg-json--soluciones-empresariales',
				mode: 'cursor',
				resizeMode: 'cover',
				actions: [
					{
						type: "hold"
					}
				]
		});
		
	} catch (_) {
		await new Promise((resolve) => {
			setTimeout(() => resolve(), 1000);
		});
		
		return generateAnimationEmpresariales();
	} 
}


async function generateAnimationBancaPrivada() {
	try {
		LottieInteractivity.create({
			player: '#banca-privada',
			container: '.animate-bg-json--banca-privada',
			mode: 'cursor',
			resizeMode: 'cover',
			actions: [
				{
						type: "hold"
				}
			]
		});
	} catch (_) {
		await new Promise((resolve) => {
			setTimeout(() => resolve(), 1000);
		});
		
		return generateAnimationBancaPrivada();
	} 
}

window.addEventListener("load", async () => {
		generateAnimationEmpresariales();
		generateAnimationBancaPrivada();
});

